SELECT product_id, CASE WHEN quantity >= 206 THEN 'HIGH' ELSE 'LOW' END AS quantity_tier, DATE_TRUNC('YEAR', last_restock) AS year_start, STDDEV_SAMP(quantity) AS quantity_stddev, STDDEV_SAMP(quantity) AS quantity_stddev_2, APPROX_PERCENTILE(quantity, 0.9) AS quantity_p90, PERCENTILE_APPROX(quantity, 0.95) AS quantity_p95, COUNT(DISTINCT id) AS distinct_ids FROM inventory GROUP BY GROUPING SETS ((product_id, CASE WHEN quantity >= 206 THEN 'HIGH' ELSE 'LOW' END, DATE_TRUNC('YEAR', last_restock)), (product_id, CASE WHEN quantity >= 206 THEN 'HIGH' ELSE 'LOW' END)) HAVING APPROX_PERCENTILE(quantity, 0.9) > 0 ORDER BY quantity_stddev NULLS LAST;
